// Conceptual Node.js / Express Session Example

// 1. User logs in
app.post('/login', (req, res) => {
  const user = checkPassword(req.body);

  // Server creates a session in memory, and AUTOMATICALLY sends a cookie 
  // to the browser containing a random ID (e.g. session_id=98765)
  req.session.userId = user.id;
  req.session.role = 'Admin';

  res.send('Logged in!');
});

// 2. User requests private data later
app.get('/dashboard', (req, res) => {
  // Server reads the cookie, looks up the session in its memory
  if (req.session.userId) {
    res.send(`Welcome Admin ${req.session.userId}`);
  } else {
    res.status(401).send('Who are you?');
  }
});
